{
 "summary": {
  "es": "憲法《けんぽう》を変《か》えるには、2つの段階《だんかい》が必要《ひつよう》です。まず、国会《こっかい》が発議《はつぎ》（国民《こくみん》に案《あん》を出《だ》すこと）をします。それには、それぞれの議院《ぎいん》の、全部《ぜんぶ》の議員《ぎいん》の3分《ぶん》の2以上《いじょう》の賛成《さんせい》がいります。次《つぎ》に、国民投票《こくみんとうひょう》でみとめられることが必要《ひつよう》です。賛成《さんせい》が、投票《とうひょう》の数《かず》の合計《ごうけい》の2分《ぶん》の1をこえるとみとめられます。",
  "hs": "憲法改正には、国会の発議（各議院の総議員の3分の2以上の賛成）と、国民投票での承認（賛成が投票総数の2分の1を超《こ》えること）の2段階が必要です。"
 },
 "blocks/0/text": {
  "es": "国民投票《こくみんとうひょう》の日《ひ》に、仕事《しごと》や出張《しゅっちょう》があったら、どうやって投票《とうひょう》する？",
  "hs": "国民投票の日に仕事や出張があったら、どうやって投票するのでしょうか？"
 },
 "blocks/1/items/0/text": {
  "es": "議員《ぎいん》が、憲法《けんぽう》を変《か》えるもとの案《あん》（憲法改正《けんぽうかいせい》原案《げんあん》）を出《だ》すには、衆議院《しゅうぎいん》で100人《にん》以上《いじょう》、参議院《さんぎいん》で50人《にん》以上《いじょう》の賛成《さんせい》がいります（国会《こっかい》法《ほう》第《だい》68条《じょう》の2）。原案《げんあん》は、それぞれの議院《ぎいん》の憲法《けんぽう》審査会《しんさかい》で、話《はな》し合《あ》われ、しらべられます（国会《こっかい》法《ほう》第《だい》102条《じょう》の6）。",
  "hs": "議員が憲法改正原案を発議するには、衆議院で100人以上、参議院で50人以上の賛成が必要です（国会法第68条の2）。原案は各議院の憲法｜審査会《しんさかい》で審査《しんさ》されます（同法第102条の6）。"
 },
 "blocks/1/items/1/text": {
  "es": "それぞれの議院《ぎいん》の、全部《ぜんぶ》の議員《ぎいん》の3分《ぶん》の2以上《いじょう》が賛成《さんせい》すると、国会《こっかい》が発議《はつぎ》し、国民《こくみん》に提案《ていあん》します（憲法《けんぽう》第《だい》96条《じょう》第《だい》1項《こう》）。",
  "hs": "各議院の総議員の3分の2以上の賛成により、国会が発議し、国民に提案します（憲法第96条第1項《こう》）。"
 },
 "blocks/1/items/2/text": {
  "es": "国民投票《こくみんとうひょう》は、発議《はつぎ》した日《ひ》から数《かぞ》えて60日《にち》以後《いご》、180日《にち》以内《いない》の、国会《こっかい》が決《き》めた日《ひ》に行《おこな》われます（国民投票法《こくみんとうひょうほう》第《だい》2条《じょう》）。",
  "hs": "国民投票は、発議した日から数えて60日以後180日以内で、国会が議決した日に行われます（国民投票法第2条）。"
 },
 "blocks/1/items/3/text": {
  "es": "賛成《さんせい》の票《ひょう》の数《かず》が、投票《とうひょう》総数《そうすう》（賛成《さんせい》の票《ひょう》と反対《はんたい》の票《ひょう》を合《あ》わせた数《かず》）の2分《ぶん》の1をこえると、みとめられた（承認《しょうにん》）ことになります（国民投票法《こくみんとうひょうほう》第《だい》126条《じょう》）。",
  "hs": "賛成の投票数が投票総数（賛成票と反対票の合計）の2分の1を超《こ》えた場合に、承認となります（国民投票法第126条）。"
 },
 "blocks/1/items/4/text": {
  "es": "みとめられたときは、天皇《てんのう》が国民《こくみん》の名《な》で、憲法《けんぽう》とひとつのものとして、すぐに公布《こうふ》（広《ひろ》く知《し》らせること）します（憲法《けんぽう》第《だい》96条《じょう》第《だい》2項《こう》）。",
  "hs": "承認されたときは、天皇が国民の名で、憲法と一体を成すものとして直ちに公布します（憲法第96条第2項《こう》）。"
 },
 "blocks/4/text": {
  "es": "国民投票《こくみんとうひょう》で投票《とうひょう》できるのは、満《まん》18歳《さい》以上《いじょう》の日本国民《にほんこくみん》です（国民投票法《こくみんとうひょうほう》第《だい》3条《じょう》）。",
  "hs": "国民投票の投票権は、年齢《ねんれい》満18歳《さい》以上の日本国民が持ちます（国民投票法第3条）。"
 },
 "blocks/5/text": {
  "es": "憲法《けんぽう》を変《か》えるべきかどうかや、その中身《なかみ》については、意見《いけん》が分《わ》かれます。このページは、手続《てつづ》きだけをあつかいます。",
  "hs": "憲法改正の是非《ぜひ》（するべきかどうか）や内容については、意見が分かれます。このページは手続きのみを扱《あつか》います。"
 }
